import datetime, random
from borax.calendars.lunardate import YEAR_INFOS, _iter_year_month
from lunarcalendar import Converter, Solar, Lunar

BASE=datetime.date(1900,1,31)  # lunar 1900-1-1
# cumulative days before each lunar year (and a sentinel after last)
cum=[0]
for info in YEAR_INFOS:
    nd=sum(md for _,md,_ in _iter_year_month(info))
    cum.append(cum[-1]+nd)

def _months(info):
    return list(_iter_year_month(info))

def solar_to_lunar(d):
    off=(d-BASE).days
    if off<0 or off>=cum[-1]: raise ValueError("out")
    # binary year
    import bisect
    yi=bisect.bisect_right(cum,off)-1
    rem=off-cum[yi]
    year=1900+yi
    for month,days,leap in _months(YEAR_INFOS[yi]):
        if rem<days: return (year,month,rem+1,leap)
        rem-=days

def lunar_to_solar(year,month,day,leap):
    yi=year-1900
    off=cum[yi]; 
    for m,days,lp in _months(YEAR_INFOS[yi]):
        if m==month and lp==leap:
            if not 1<=day<=days: raise ValueError("bad day")
            return BASE+datetime.timedelta(days=off+day-1)
        off+=days
    raise ValueError("no such month")

# exhaustive cross check vs lunarcalendar (solar->lunar) for every day 1900-02-17 .. 2100-12-31
d=datetime.date(1900,2,17); end=datetime.date(2100,12,31); n=0; errs=0
while d<=end:
    y,m,dd,lp=solar_to_lunar(d)
    r=Converter.Solar2Lunar(Solar(d.year,d.month,d.day))
    if (r.year,r.month,r.day,bool(r.isleap))!=(y,m,dd,bool(lp)):
        errs+=1
        if errs<=5: print("MISMATCH",d,(y,m,dd,lp),(r.year,r.month,r.day,r.isleap))
    n+=1; d+=datetime.timedelta(days=1)
print("solar->lunar days:",n,"errors:",errs)

# round trip lunar->solar->lunar random
random.seed(1); rt=0
for _ in range(200000):
    yi=random.randrange(201); year=1900+yi
    seqs=_months(YEAR_INFOS[yi]); mo,days,lp=random.choice(seqs); day=random.randint(1,days)
    s=lunar_to_solar(year,mo,day,lp)
    b=solar_to_lunar(s)
    if b!=(year,mo,day,lp):
        rt+=1
        if rt<=5: print("RT FAIL",(year,mo,day,lp),s,b)
print("roundtrip errors:",rt)

# known Spring Festivals
for y in [1900,2000,2024,2025,2100]:
    print("春节",y,lunar_to_solar(y,1,1,0))
